// Ported from prototypes/deadlock by build-deadlock-bridge.py, then wired to live deadlock-api data by hand (DONI-446). Edit here; do not regenerate.
// Tier list rows from /analytics/hero-stats (DONI-482); pure so app/test-deadlock.js can check it on a fixture.
// ponytail: tier = win-rate percentile (S top 10%, A 20%, B 40%, C 20%, D 10%); swap for a sample-weighted score if small brackets look noisy.
window.deadlockTierRows = function(stats, minMatches = 50) {
  const games = stats.reduce((n, h) => n + h.matches, 0) / 12 || 1; // 12 heroes per match
  const rows = stats.filter(h => h.matches >= minMatches).map(h => ({ hid:h.hero_id, wr:h.wins/h.matches, pick:h.matches/games, kda:(h.total_kills + h.total_assists)/Math.max(1, h.total_deaths), souls:h.total_net_worth/h.matches, matches:h.matches })).sort((a,b) => b.wr - a.wr);
  rows.forEach((r, i) => { const p = i / rows.length; r.tier = p < .1 ? 'S' : p < .3 ? 'A' : p < .7 ? 'B' : p < .9 ? 'C' : 'D'; });
  return rows;
};
