  const t = text.trim(), my = ++searchSeq;
  if(t.length < 3 || /^\d+$/.test(t)) return;
  searchTimer = setTimeout(() => cached('/players/steam-search', {search_query:t, limit:5}).catch(() => []).then(list => { if(my === searchSeq) renderSearch(text, list); }), 350);
