function elapsed() { const seconds = Math.max(0,Math.floor((Date.now() - queueStarted) / 1000)); return `${String(Math.floor(seconds / 60)).padStart(2,'0')}:${String(seconds % 60).padStart(2,'0')}`; }
function syncQueue() { document.querySelector('#header-status').textContent = queueState === 'idle' ? 'Companion ready' : queueState === 'searching' ? 'Watching · Demo' : 'Queue popped · Demo'; document.querySelector('#queue-status').textContent = queueState === 'idle' ? 'Local demo · Ready when you are' : queueState === 'searching' ? 'Demo running · You can step away' : 'Your simulated queue is ready'; }
function renderCompanion() { body.innerHTML = header('QueuePop / Your companion','The city can wait.','Try the queue flow, then get back to real life. This demo does not connect to a game or send notifications.') + `<div class="queue-dial"><strong id="queue-clock">${queueState === 'idle' ? 'Ready' : queueState === 'searching' ? elapsed() : 'It’s time'}</strong><small>${queueState === 'idle' ? 'LOCAL DEMO' : queueState === 'searching' ? 'WATCHING · DEMO' : 'QUEUE POPPED'}</small></div><div class="action-row queue-controls">${queueState === 'idle' ? '<button class="action" data-queue="start">Start demo queue</button>' : queueState === 'searching' ? '<button class="action" data-queue="pop">Simulate queue pop</button><button class="action secondary" data-queue="reset">Cancel demo</button>' : '<button class="action" data-queue="reset">Back at my desk</button>'}</div><p class="demo-explanation">${queueState === 'searching' ? 'Stretch your legs. The timer keeps running if you close this panel. Use “Simulate queue pop” when you’re ready.' : queueState === 'ready' ? 'This is your simulated ready check. No game action has been taken.' : 'Start, step away, and try a ready check. You’re in control of the demo.'}</p><fieldset class="notification-options"><legend>Remembered preferences · Demo only</legend><label><input type="checkbox" data-pref="phone" ${saved.phone ? 'checked' : ''}>Phone alert</label><label><input type="checkbox" data-pref="discord" ${saved.discord ? 'checked' : ''}>Discord alert</label></fieldset>`; }
const pageNames = {heroes:'Hero dossiers',builds:'Build ledger',history:'Match history',guides:'Field guide',companion:'Your companion'};
function liftPageHeading() {
  const destination = document.querySelector('#page-title');
  const intro = body.querySelector('.archive-intro');
  destination.replaceChildren();
  if(intro) destination.append(intro);
  else {
    for(const element of body.querySelectorAll(':scope > .sheet-kicker, :scope > #sheet-title, :scope > .sheet-intro')) destination.append(element);
  }
  const oldHeading = destination.querySelector('#sheet-title');
  if(oldHeading) {
    const heading = document.createElement('h1');
    heading.id = 'sheet-title'; heading.tabIndex = -1; heading.textContent = oldHeading.textContent;
    oldHeading.replaceWith(heading);
  }
}
function renderPage(name, focus = true) {
  const renderers = {'':renderCity,heroes:renderHeroes,builds:renderBuilds,history:renderHistory,guides:renderGuides,companion:renderCompanion};
  activePanel = renderers[name] ? name : '';
  document.body.classList.add('in-archive');
  sheet.dataset.panel = activePanel || 'city';
  document.querySelector('#toast').hidden = true;
  for(const link of document.querySelectorAll('.city-nav a')) {
    const current = (link.dataset.open || '') === activePanel;
    link.classList.toggle('nav-current',current);
    if(current) link.setAttribute('aria-current','page'); else link.removeAttribute('aria-current');
  }
  document.title = `${pageNames[activePanel] || 'The city'} · Deadlock · QueuePop`;
  document.querySelector('#page-location').textContent = pageNames[activePanel] || 'The city';
  renderers[activePanel]();
  if(activePanel === 'guides' || activePanel === 'companion') liftPageHeading();
  window.scrollTo({top:0,behavior:'instant'});
  if(focus) {
    const target = document.querySelector('#sheet-title');
    target.tabIndex = -1; target.focus({preventScroll:true});
  }
}
function openPage(name) {
  const route = name && pageNames[name] ? name : '';
  const hash = '#/' + route;
  if(location.hash !== hash) history.pushState({},'',hash);
  renderPage(route);
}
function routeFromAddress(focus = true) {
  const [route, subject] = location.hash.replace(/^#\/?/,'').split('/');
  if(route === 'city' || route === 'sheet-title') return;
  if(route === 'heroes' && heroes.some(hero => hero.id === subject) && activePanel === 'heroes') {
    if(inspectedHero !== subject) {
      renderHero(subject);
      if(focus) document.querySelector('.hero-name').focus({preventScroll:true});
    }
    return;
  }
  renderPage(pageNames[route] ? route : '',focus);
}


document.addEventListener('click', event => {
  if(event.target.closest('.skip')) {
    event.preventDefault();
    const target = document.querySelector('#sheet-title');
    target.tabIndex = -1; target.focus({preventScroll:true}); target.scrollIntoView({block:'start'}); return;
  }
  const button = event.target.closest('button, a[data-open], a[data-home]'); if(!button) return;
  if(button.dataset.open) { event.preventDefault(); openPage(button.dataset.open); }

  if(button.hasAttribute('data-home')) { event.preventDefault(); openPage(''); }
  if(button.dataset.hero) inspectHero(button.dataset.hero);
  if(button.dataset.file) inspectHero(button.dataset.file,button.dataset.fileStep);
  if(button.hasAttribute('data-directory-return')) {
    document.querySelector('.directory').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches ? 'instant' : 'smooth'});
    document.querySelector('#hero-search').focus({preventScroll:true});
  }
  if(button.dataset.select) {
    const hero = heroes.find(item => item.id === button.dataset.select);
    selectedHero = hero.id; persist(); renderRoster(document.querySelector('#hero-search').value);
    button.textContent = `${hero.name} selected ✓`; button.setAttribute('aria-pressed','true');
    button.parentElement.querySelector('span').textContent = 'Your person at the city desk';
    toast(`${hero.name} selected${storageAvailable ? ' and remembered on this device' : ' for this visit'}.`);
  }
  if(button.dataset.ledgerHero) { const id = Number(button.dataset.ledgerHero); L.hero = L.hero === id ? null : id; L.owned.clear(); renderBuilds(); document.querySelector(`[data-ledger-hero="${id}"]`).focus({preventScroll:true}); }
  if(button.dataset.ledgerEnemy) { const id = Number(button.dataset.ledgerEnemy); L.enemies.has(id) ? L.enemies.delete(id) : L.enemies.add(id); renderBuilds(); document.querySelector(`[data-ledger-enemy="${id}"]`).focus({preventScroll:true}); }
  if(button.hasAttribute('data-ledger-reset')) { L.hero = null; L.enemies.clear(); L.owned.clear(); renderBuilds(); }
  if(button.dataset.sort) { const k = button.dataset.sort; L.dir = L.sort === k ? -L.dir : (k === 'name' ? 1 : -1); L.sort = k; renderLedgerRows(); }
  if(button.dataset.own) { const id = Number(button.dataset.own); L.owned.has(id) ? L.owned.delete(id) : L.owned.add(id); loadLedger(); }
  if(button.dataset.report) { currentMatch = button.dataset.report; renderMatchReport(); revealCasework('.report-cover'); }
  if(button.hasAttribute('data-clear-records')) { recordFilter = 'All'; recordHero = 'All'; renderHistory(); document.querySelector('[data-filter="All"]').focus({preventScroll:true}); }
  if(button.dataset.heroBuild) { const hero = heroes.find(item => item.id === button.dataset.heroBuild); L.hero = hero?.hid ?? L.hero; L.enemies.clear(); L.owned.clear(); openPage('builds'); }
  if(button.hasAttribute('data-overlay-launch')) launchOverlay();
  if(button.hasAttribute('data-deadlock-play')) playDeadlock(button);
  if(button.dataset.tierHero) { const id = Number(button.dataset.tierHero); T.open = T.open === id ? null : id; renderTierRows(); document.querySelector(`[data-tier-hero="${id}"]`).focus({preventScroll:true}); }
  if(button.dataset.gotoHero || button.dataset.searchHero) { const id = button.dataset.gotoHero || button.dataset.searchHero; closeSearch(); history.pushState({},'','#/heroes/' + id); renderPage('heroes'); }
  if(button.dataset.searchItem) showItem(Number(button.dataset.searchItem));
  if(button.dataset.searchPlayer) { viewing = button.dataset.searchPlayer; closeSearch(); recordsFor = ''; openPage(''); }
  if(button.hasAttribute('data-view-own')) { viewing = account; recordsFor = ''; renderPage(activePanel, false); }
  if(button.hasAttribute('data-acct-edit')) { const edit = document.querySelector('#card-edit'); edit.hidden = !edit.hidden; if(!edit.hidden) document.querySelector('#record-acct').focus(); }
  if(button.dataset.filter) { recordFilter = button.dataset.filter; renderHistory(); document.querySelector(`[data-filter="${recordFilter}"]`).focus({preventScroll:true}); }
  if(button.dataset.queue) { if(button.dataset.queue === 'start') { queueState = 'searching'; queueStarted = Date.now(); } else if(button.dataset.queue === 'pop') { queueState = 'ready'; toast('Your queue popped (simulated alert).'); } else queueState = 'idle'; syncQueue(); renderCompanion(); document.querySelector('.queue-controls button').focus({preventScroll:true}); }
});
document.addEventListener('input', event => { if(event.target.id === 'hero-search') renderRoster(event.target.value); if(event.target.id === 'city-search') onSearch(event.target.value); });
document.addEventListener('keydown', event => { if(event.key === 'Escape' && event.target.id === 'city-search') closeSearch(); });
document.addEventListener('change', event => {
  if(event.target.id === 'record-acct') { setAccount(event.target.value); recordsFor = ''; renderPage(activePanel, false); document.querySelector('#record-acct')?.focus({preventScroll:true}); }
  if(['tier-rank','tier-patch','tier-days'].includes(event.target.id)) { T.rank = document.querySelector('#tier-rank').value; T.patch = document.querySelector('#tier-patch').value; T.days = document.querySelector('#tier-days').value; T.open = null; loadTiers(); }
  if(event.target.id === 'ledger-days' || event.target.id === 'ledger-minm') { L.days = Number(document.querySelector('#ledger-days').value); L.minm = Number(document.querySelector('#ledger-minm').value); L.heroWR = {}; loadLedger(); }
  if(event.target.id === 'record-hero') { recordHero = event.target.value; renderHistory(); document.querySelector('#record-hero').focus({preventScroll:true}); }
  if(event.target.dataset.pref) { saved[event.target.dataset.pref] = event.target.checked; persist(); }
});
setInterval(() => { const clock = document.querySelector('#queue-clock'); if(!host.hidden && !sheet.hidden && activePanel === 'companion' && queueState === 'searching' && clock) clock.textContent = elapsed(); },1000);

loadLive();
// The account id lives in config (deadlock_account_id); localStorage is the fallback outside the host.
bridge()?.get_deadlock_account?.().then(id => {
  if(id && id !== account) { const was = viewing === account; account = id; if(was) viewing = id; if(!host.hidden) renderPage(activePanel, false); }
  else if(!id && account) bridge().set_deadlock_account?.(account);
}).catch(() => {});

